<?php
function compact_history_controls($page){$GLOBALS['rs8_history_page']=$page;}
function compact_history_footer($page){
 ob_start();
 $sql=['beginning'=>"SELECT COUNT(*) FROM import_batches WHERE import_type='Beginning Balance'",'file_generator'=>"SELECT COUNT(*) FROM import_batches WHERE import_type='Platform Inventory Generator'",'receipts'=>"SELECT COUNT(*) FROM inflow_batches WHERE batch_type='Receipt PDF'",'allocation_history'=>'SELECT COUNT(*) FROM allocation_batches','outflow'=>"SELECT (SELECT COUNT(*) FROM import_batches WHERE import_type='Orders')+(SELECT COUNT(*) FROM outflows WHERE import_batch_id IS NULL)",'nonsellable'=>'SELECT COUNT(*) FROM non_sellable','transfers'=>'SELECT COUNT(*) FROM platform_transfers','reconciliation'=>'SELECT COUNT(*) FROM reconciliation_batches'][$page];$total=$GLOBALS['rs8_history_total']??(int)db()->query($sql)->fetchColumn();$all=($_GET['history']??'')==='all';$offset=max(0,(int)($_GET['offset']??0));$p=$_GET;$p['page']=$page;unset($p['offset']);echo '<div class="modal-actions history-compact"><span>'.($all?'History: '.$total.' records':'Latest 10 transactions').'</span>';if(!$all){$p['history']='all';echo '<a class="btn ghost" href="?'.e(http_build_query($p)).'">View all</a>';}else{unset($p['history']);echo '<a class="btn ghost" href="?'.e(http_build_query($p)).'">Recent</a>';$p['history']='all';echo rs8_pagination($total,$offset,50,$p);}echo '</div>';
 $GLOBALS['rs8_history_footer']=ob_get_clean();
}
